#pragma once
#include "meta/sqlite_results.h"
#include "net/authoritative_match.h"
#include "tests/authority_fixture.h"
namespace study_review_test {
inline study_net::MatchRecord match(std::uint64_t key,bool swapped=false) {
    using namespace study_net;
    AuthoritativeMatch game(9,swapped?202:101,swapped?101:202,77,1000);
    for(std::uint32_t tick=0;game.result().state==MatchState::incomplete;++tick) {
        study_authority_test::require(tick<1000);
        game.submit(101,study_authority_test::frame(tick,{0}));
        game.submit(202,study_authority_test::frame(tick,{study_input::drop}));
    }
    auto record=game.record(key);study_authority_test::require(record.has_value());return *record;
}
}

explicit ReviewReader(const std::string& path) {
        if(path.empty() || path.find('\0')!=std::string::npos)throw std::invalid_argument("review database path");
        sqlite3* raw=nullptr;
        const auto rc=sqlite3_open_v2(path.c_str(),&raw,SQLITE_OPEN_READONLY,nullptr);
        db_.reset(raw);
        if(rc!=SQLITE_OK || !raw)throw std::runtime_error("review database open failed");
        if(sqlite3_busy_timeout(raw,1000)!=SQLITE_OK || !read_only())throw std::runtime_error("review read-only setup failed");
        Statement app(raw,"PRAGMA application_id"),version(raw,"PRAGMA user_version");
        if(!app.next() || app.integer_column(0)!=1413829714 || !version.next() || version.integer_column(0)!=7)
            throw std::runtime_error("unsupported review schema");
    }
    bool read_only()const noexcept{return sqlite3_db_readonly(db_.get(),"main")==1;}

ReviewSample read(std::size_t limit) {
        if(!limit || limit>kMaxReviewRows)throw std::invalid_argument("review row limit");
        Statement q(db_.get(),"SELECT id,player_a,player_b,winner,ticks FROM matches ORDER BY id DESC LIMIT ?1");
        q.integer(1,static_cast<sqlite3_int64>(limit+1));
        ReviewSample sample{{},limit,false};sample.rows.reserve(limit);
        while(q.next()) {
            if(sample.rows.size()==limit){sample.has_older=true;continue;}
            const auto id=q.integer_column(0);
            if(id<=0)throw std::runtime_error("invalid result identity");
            sample.rows.push_back({static_cast<std::uint64_t>(id),decimal(q.text_column(1)),
                decimal(q.text_column(2)),q.is_null(3)?0:decimal(q.text_column(3)),decimal(q.text_column(4))});
        }
        return sample; // One SELECT reads one coherent SQLite snapshot.
    }

for(const auto& row:sample.rows) {
        if(!row.row || (previous && row.row>=previous) || !row.player_a || !row.player_b ||
           row.player_a==row.player_b || !row.ticks ||
           (row.winner && row.winner!=row.player_a && row.winner!=row.player_b))
            throw std::invalid_argument("invalid authoritative review row");
        previous=row.row;
        const std::array<std::uint64_t,2> pair{std::min(row.player_a,row.player_b),std::max(row.player_a,row.player_b)};
        auto& count=pairs[pair];++count.games;
        if(row.winner==pair[0])++count.lower_wins;
        if(row.winner==pair[1])++count.upper_wins;
        if(row.ticks<=short_tick_limit)++count.short_games;
    }

if (p.repeat_matches == 0 || p.one_sided_wins == 0 || p.short_matches == 0) {
        throw std::invalid_argument("review policy thresholds must be non-zero");
    }
    // Consistency: total wins must not exceed games (checked without overflow),
    // and lower_wins must not exceed games - upper_wins.
    if (c.upper_wins > c.games || c.lower_wins > c.games - c.upper_wins) {
        throw std::invalid_argument("inconsistent counters: wins exceed games");
    }
    if (c.short_games > c.games) {
        throw std::invalid_argument("inconsistent counters: short_games exceed games");
    }

unsigned flags = 0;

    if (c.games >= p.repeat_matches) {
        flags |= repeated_pair;
    }

    const std::uint64_t hi = std::max(c.lower_wins, c.upper_wins);
    const std::uint64_t lo = std::min(c.lower_wins, c.upper_wins);
    if (hi >= p.one_sided_wins && lo == 0) {
        flags |= one_sided;
    }

    if (c.short_games >= p.short_matches) {
        flags |= short_results;
    }

    return flags;
}

struct ReviewReport {
    ReviewPolicy policy;
    std::uint64_t short_tick_limit;
    std::size_t rows_read,requested;
    std::uint64_t newest=0,oldest=0;
    bool has_older;
    std::vector<PairReview> pairs;
};
